globalThis.ragSearchTexts=globalThis.ragSearchTexts||{};globalThis.ragSearchTexts["11"]={"1704":"Сборы к ВсОШ по ИИ\nПриветствуем в чате Сборов к ВсОШ по ИИ!\n\n🔘 Занятия стартуют 7 февраля\n\n🔘 Основная страничка сборов — https://algocode.ru/vsosh_ai/\n\nПодробности будем публиковать здесь ближе к началу)\n\nОчень рады вам!\n\nКраткое описание:\nМатериалы прошедших февральско-мартовских сборов 2026 к ВсОШ по ИИ: записи занятий, ноутбуки и домашние задания по ML и нейросетям.\nПоисковая тема: даты и расписание."};
